WITH monthly_store AS (SELECT d.d_year, d.d_month_seq, SUM(sr.sr_net_loss) AS total_store_net_loss, SUM(COALESCE(cr.cr_net_loss,0)) AS total_catalog_net_loss, COALESCE(AVG(cc.cc_gmt_offset),0) AS avg_gmt_offset FROM date_dim d LEFT JOIN store_returns sr ON sr.sr_returned_date_sk = d.d_date_sk LEFT JOIN catalog_returns cr ON cr.cr_returned_date_sk = d.d_date_sk LEFT JOIN call_center cc ON cc.cc_open_date_sk = d.d_date_sk WHERE d.d_year = 2022 GROUP BY d.d_year, d.d_month_seq), monthly_with_moving AS (SELECT *, AVG(total_store_net_loss) OVER (PARTITION BY d_year ORDER BY d_month_seq ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS moving_avg_3_months FROM monthly_store) SELECT d_year, d_month_seq, total_store_net_loss, total_catalog_net_loss, moving_avg_3_months, DENSE_RANK() OVER (ORDER BY moving_avg_3_months DESC) AS loss_month_rank, avg_gmt_offset FROM monthly_with_moving ORDER BY d_year, d_month_seq
